mapper.select:
SELECT id, group_code AS groupCode, group_name AS groupName, description, status, is_system AS isSystem, order_num AS orderNum, create_time AS createTime, update_time AS updateTime, create_user AS createUser, update_user AS updateUser FROM sys_job_group WHERE status = 1
AND (group_code LIKE CONCAT('%', #{keyword}, '%') OR group_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY order_num LIMIT #{limit}
